// Returns the minimum element of a non-empty array.
fn min_array(a: Vec<i64>) -> i64 {
    // Precondition: a.len() >= 1
    let mut min_val = a[0];
    for &x in a.iter().skip(1) {
        if x < min_val {
            min_val = x;
        }
    }
    min_val
}

